def transform(grid):
    h, w = len(grid), len(grid[0])

    # Locate the full grid lines that divide the panels.
    sep_rows = [r for r in range(h) if grid[r][0] != 0 and all(v == grid[r][0] for v in grid[r])]
    sep_cols = [c for c in range(w) if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h))]

    row_ranges = []
    start = 0
    for r in sep_rows:
        if start < r:
            row_ranges.append((start, r))
        start = r + 1
    if start < h:
        row_ranges.append((start, h))

    col_ranges = []
    start = 0
    for c in sep_cols:
        if start < c:
            col_ranges.append((start, c))
        start = c + 1
    if start < w:
        col_ranges.append((start, w))

    # For each color, infer which neighboring panel columns are mirror partners
    # from panels that already contain a matching reflected pair.
    partner_pairs = set()
    for a in range(len(col_ranges) - 1):
        b = a + 1
        for r0, r1 in row_ranges:
            c0, c1 = col_ranges[a]
            d0, d1 = col_ranges[b]
            if c1 - c0 != d1 - d0 or r1 - r0 != r1 - r0:
                continue
            width = c1 - c0

            left = {(rr - r0, cc - c0, grid[rr][cc])
                    for rr in range(r0, r1) for cc in range(c0, c1)
                    if grid[rr][cc] != 0}
            right = {(rr - r0, cc - d0, grid[rr][cc])
                     for rr in range(r0, r1) for cc in range(d0, d1)
                     if grid[rr][cc] != 0}
            if not left or not right:
                continue

            reflected_left = {(rr, width - 1 - cc, color) for rr, cc, color in left}
            if reflected_left == right:
                colors = {color for _, _, color in left}
                if colors == {color for _, _, color in right}:
                    for color in colors:
                        partner_pairs.add((color, a, b))

    out = [row[:] for row in grid]

    # Complete each inferred mirror pair wherever one panel is empty.
    for color, a, b in partner_pairs:
        for r0, r1 in row_ranges:
            for src, dst in ((a, b), (b, a)):
                s0, s1 = col_ranges[src]
                d0, d1 = col_ranges[dst]
                if s1 - s0 != d1 - d0:
                    continue

                source_cells = [(rr, cc - s0) for rr in range(r0, r1)
                                for cc in range(s0, s1) if grid[rr][cc] == color]
                if not source_cells:
                    continue
                if any(grid[rr][cc] != 0 for rr in range(r0, r1)
                       for cc in range(d0, d1)):
                    continue

                width = s1 - s0
                for rr, local_c in source_cells:
                    out[rr][d0 + width - 1 - local_c] = color

    return out
